update public.products set description='Smoked Ponmo is processed cow skin exposed to smoke or heat, giving it a darker appearance and characteristic smoky flavour for soups, stews, sauces and other thoroughly cooked dishes.', handling_protocols=array['Inspect for visible mold, abnormal residue or obvious spoilage before preparation.','Use clean water for any rinsing or soaking and keep preparation water away from other foods.','Cook thoroughly before consumption.']::text[], storage_tips=array['If the smoked Ponmo is moist or pliable, refrigerate immediately and use within about 1–2 days or freeze for longer storage.','If it is fully dried and hard, keep airtight, cool and dry and use within about 2–4 weeks pending a verified moisture specification.','Discard product that becomes moldy, slimy or strongly off-smelling.']::text[] where name='Smoked Pomo' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
